<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{authAPI}from'../../api/auth';import{APIError}from'../../api/client';import AuthShell from'../../components/AuthShell.vue';import{useToast}from'../../composables/useToast';const form=reactive({email:'',verification_code:'',new_password:'',confirm:''}),step=ref<1|2>(1),error=ref(''),router=useRouter(),toast=useToast();async function request(){error.value='';try{await authAPI.forgot(form.email);step.value=2}catch(e){error.value=e instanceof APIError?e.message:'请求失败'}}async function reset(){error.value='';if(form.new_password.length<12||form.new_password.length>128){error.value='密码长度必须为 12–128 个字符';return}if(form.new_password!==form.confirm){error.value='两次输入的密码不一致';return}try{await authAPI.reset(form);toast.success('密码已重置，请登录');await router.replace('/login')}catch(e){error.value=e instanceof APIError?e.message:'重置失败'}}</script>
<template><AuthShell><section class="auth-card panel"><RouterLink to="/login">← 返回登录</RouterLink><h1>找回密码</h1><p class="muted">{{step===1?'先验证注册邮箱':'输入验证码并设置新密码'}}</p><form v-if="step===1" @submit.prevent="request"><label>注册邮箱<input v-model="form.email" type="email" required/></label><button class="button primary wide">发送重置验证码</button></form><form v-else @submit.prevent="reset"><label>邮箱<input v-model="form.email" type="email" readonly/></label><label>验证码<input v-model="form.verification_code" required/></label><label>新密码<input v-model="form.new_password" type="password" minlength="12" maxlength="128" required/></label><label>确认新密码<input v-model="form.confirm" type="password" minlength="12" maxlength="128" required/></label><button class="button primary wide">重置密码</button></form><p v-if="error" class="error">{{error}}</p></section></AuthShell></template>
